declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/lms_v1360.php';sk1360_require_login();$id=(int)($_GET['id']??$_POST['course_id']??0);$c=sk1360_course($id);if(!$c||!sk1360_teacher_can_course($id)){http_response_code(403);exit('Course access denied.');}$msg='';$err='';try{$msg=sk1360_post_action('teacher');}catch(Throwable $e){$err=$e->getMessage();}$pdo=sk1360_db();$tid=sk1360_tid();$csrf=sk1360_csrf();$sections=sk1360_course_sections($id);$q=$pdo->prepare('SELECT * FROM lms_assignments_v1360 WHERE tenant_id=? AND course_id=? ORDER BY id DESC');$q->execute([$tid,$id]);$assignments=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$q=$pdo->prepare('SELECT * FROM lms_quizzes_v1360 WHERE tenant_id=? AND course_id=? ORDER BY id DESC');$q->execute([$tid,$id]);$quizzes=$q->fetchAll(PDO::FETCH_ASSOC)?:[];$q=$pdo->prepare('SELECT * FROM lms_enrollments_v1360 WHERE tenant_id=? AND course_id=? ORDER BY id DESC');$q->execute([$tid,$id]);$enrollments=$q->fetchAll(PDO::FETCH_ASSOC)?:[];sk1360_lms_shell('Teaching · '.$c['title'],'teacher');?><section class="portal-hero"><div><a href="/teacher/lms.php" class="back">← Teacher Dashboard</a><span class="eyebrow">TEACHING WORKSPACE</span><h1><?=sk1360_h($c['title'])?></h1><p><?=count($enrollments)?> learners · <?=count($sections)?> curriculum sections</p></div></section><?php if($msg):?><div class="lms-alert ok"><?=sk1360_h($msg)?></div><?php endif;?><?php if($err):?><div class="lms-alert err"><?=sk1360_h($err)?></div><?php endif;?>
