uired></label><label>Message<textarea name="body" rows="4" required></textarea></label><input type="hidden" name="audience" value="students"><button>Publish</button></form></section></div>
<section class="portal-panel"><h2>Curriculum</h2><div class="curriculum"><?php foreach($sections as $s):?><article><h3><?=sk1360_h($s['title'])?></h3><?php foreach($s['lessons'] as $l):?><div class="lesson-row"><span><?=sk1360_h($l['lesson_type'])?></span><b><?=sk1360_h($l['title'])?></b></div><?php endforeach;?></article><?php endforeach;?></div></section>
